body.script:
//
					const slides = document.querySelectorAll('.slide');
					const ind = document.getElementById('ind');
					let cur = 0;

					function show(i) {
						slides[cur].classList.remove('active');
						cur = ((i % slides.length) + slides.length) % slides.length;
						const slide = slides[cur];
						const iframe = slide.querySelector('iframe');
						if (!iframe.dataset.loaded) {
							iframe.src = slide.dataset.src;
							iframe.dataset.loaded = '1';
						}
						slide.classList.add('active');
						ind.textContent = slide.dataset.label;
					}

					show(0);

					document.addEventListener('keydown', e => {
						if (e.key === 'ArrowRight') show(cur + 1);
						else if (e.key === 'ArrowLeft') show(cur - 1);
					});

					let touchX = null;
					const overlay = document.getElementById('swipe-overlay');
					overlay.addEventListener('touchstart', e => {
						touchX = e.touches[0].clientX;
					}, { passive: true });
					overlay.addEventListener('touchend', e => {
						if (touchX === null) return;
						const dx = e.changedTouches[0].clientX - touchX;
						touchX = null;
						if (Math.abs(dx) < 40) return;
						show(dx < 0 ? cur + 1 : cur - 1);
					}, { passive: true });
				//

//
					const cfg              = document.getElementById('cfg').dataset;
					const INSTRUMENT       = cfg.instrument;
					const ASSET            = cfg.asset;
					// Candles are Binance spot (see dankbit.trade.get_candles) —
					// BTC/ETH are the only assets this addon ever serves a chart
					// for, so this string concat mirrors the server-side
					// _BINANCE_SYMBOL_MAP without needing a new cfg field.
					document.getElementById('exchange-label').textContent = 'Binance Spot · ' + ASSET + 'USDT';
					const MONTHLY_INST     = cfg.monthly || '';
					const REFRESH          = parseInt(cfg.refresh, 10) * 1000;
					// Also drives Bands' own poll interval (see setInterval(refreshBands, ...)
					// below) — not just the Zones boxes despite the name/setting.
					const ZONES_BOX_REFRESH = parseInt(cfg.zonesBoxRefresh, 10) * 1000;
					const ZONES_BOX_WINDOW_HOURS = parseInt(cfg.zonesBoxWindowHours, 10);
					const SHOW_DAILY_LINES   = cfg.showDaily !== 'false';
					const SHOW_WEEKLY_LINES  = cfg.showWeekly !== 'false';
					const SHOW_MONTHLY_LINES = cfg.showMonthly !== 'false';
					// Only true on /oi/<asset> — /chart/<asset> and
					// /mp/<instrument> always pass show_gamma_point="false"
					// (see _build_tv_chart_context).
					const SHOW_GAMMA_POINT = cfg.showGammaPoint === 'true';
					// Only true on /mp/<instrument> — the restored "Strike
					// Gamma" indicator (see drawStrikeGammaLines below), one
					// price line per distinct strike rather than /oi/<asset>'s
					// single top-strike-per-scope "Top OI(s)" line set.
					const SHOW_STRIKE_GAMMA = cfg.showStrikeGamma === 'true';
					// The instrument /mp/<instrument> was requested with
					// (e.g. "BTC-25JUL26") — unrelated to INSTRUMENT above
					// (the configured *weekly* expiry), this is whatever
					// specific expiry the URL named, used as the isolated
					// cutoff for gamma-by-strike-at (see refreshStrikeGamma) —
					// that one instrument's own trades only, not cumulative
					// through it the way Top OI(s)' scopes are.
					const STRIKE_GAMMA_INSTRUMENT = cfg.strikeGammaInstrument || '';
					const SGI_URL = STRIKE_GAMMA_INSTRUMENT ? '/api/gamma-by-strike-at/' + STRIKE_GAMMA_INSTRUMENT : '';
					// Thales Forecast candle colors — user-configurable via
					// Settings → Dankbit → Thales Forecast (res.config.settings),
					// defaults are light red/green so forecast candles stay
					// easily distinguishable from the real teal/red candle series.
					const FORECAST_UP_COLOR = cfg.forecastUpColor || '#a5d6a7';
					const FORECAST_DOWN_COLOR = cfg.forecastDownColor || '#ef9a9a';
					const FORECAST_WICK_UP_COLOR = cfg.forecastWickUpColor || '#66bb6a';
					const FORECAST_WICK_DOWN_COLOR = cfg.forecastWickDownColor || '#e57373';
					// /oi/<asset> and /mp/<instrument> are the minimal pages
					// (candles + exactly one gamma indicator each — no
					// Weekly/Monthly/All/Daily delta=0 lines, no zones
					// boxes/extrema, no S/D (Lines)/Zones/Bands/Thales Forecast
					// checkboxes); the footer (trade count/nearest expiry) is
					// untouched either way.
					const MINIMAL_CHART = SHOW_GAMMA_POINT || SHOW_STRIKE_GAMMA;
					// User-toggleable via the "S/D" checkbox next to the Ruler
					// button (Delta Chart only — the Gamma Chart has its own,
					// unrelated "Top OI(s)" checkbox instead) — hides every
					// horizontal price-line indicator (delta=0 sets) and, to
					// actually cut server load rather than just hiding the result
					// client-side, makes each of their refresh*() functions skip
					// the fetch entirely while off (see onToggleLines() below).
					// refreshMonthlyDeltaZero() is the one exception — it always
					// fetches regardless, since its trade_count feeds the footer.
					// Unchecked/off by default, matching the checkbox's own
					// default (unchecked) state above.
					let SHOW_ALL_LINES = false;
					// User-toggleable via the "Zones" checkbox (Delta Chart only,
					// right after "S/D") — controls the yellow top/bottom
					// zero-crossing boxes (High Zone/Low Zone) and the teal Seller
					// Max Profit/Buyer Max Loss box (Middle Zone), i.e. everything
					// refreshZonesBoxes()/clearZonesBoxes() draw. Checked/on by
					// default (matching the checkbox's own default-checked state
					// above), since these boxes were always-on before this flag
					// existed — unchecking it stops refreshZonesBoxes() from
					// calling the server at all, purely to reduce server load.
					// This has no effect on dankbit.bands either way: get_box()
					// (which /api/zones-box/<asset> calls) never persists,
					// checked or not — only the 4-hourly compute_snapshot() cron
					// ever writes to that model.
					let SHOW_ZONES_BOXES = true;
					// User-toggleable via the "Bands" checkbox (Delta Chart
					// only — this indicator is already suppressed on DG Chart via
					// MINIMAL_CHART, so this control isn't shown there at all, see the
					// t-if on its markup). Controls only the High/Resistance + Low/Support +
					// Gamma Band lines (green/red/dashed violet) — deliberately NOT
					// the yellow/teal zones boxes, which have their own separate
					// "Zones" checkbox instead (SHOW_ZONES_BOXES above). Stops
					// refreshBands() from calling the server at all while off.
					// refreshBands() only ever reads the already-persisted
					// dankbit.bands rows (/api/bands/<asset>) — it
					// never triggers a new computation, for any expiry_index. Every
					// tracked expiry's row (see TRACKED_EXPIRY_COUNT) is computed and
					// refreshed solely by the 4-hourly compute_snapshot() cron;
					// nothing this browser does — checking this box, leaving it
					// checked, or polling while it's open — causes new extrema to be
					// computed.
					let SHOW_BANDS = false;
					// Trade window used by the yellow/teal zones boxes (Delta Chart
					// only, "Zones from" dropdown next to "Bands") — 'midnight' is the
					// original since-00:00-UTC-through-now default; 'hours' switches
					// to the trailing ZONES_BOX_WINDOW_HOURS hours instead (see
					// dankbit.zones_box_window_hours setting). Only 'hours' is ever
					// sent as a query param (see refreshZonesBoxes()) — a live,
					// non-persisted override on the server side (see get_box()'s
					// hours param); the 4-hourly compute_snapshot() cron and every
					// other viewer's default midnight-based view are completely
					// unaffected either way.
					let ZONES_BOX_WINDOW_MODE = 'midnight';
					// "Top OI(s)" checkbox (Gamma Chart only) — replaces the
					// old separate "Strike Gamma"/"Strike Gamma Nearest"/
					// "Strike Gamma Weekly"/"Strike Gamma Monthly" checkboxes
					// with one: instead of drawing every strike that has
					// traded (the old light-gray-to-black gradient), this
					// draws exactly one line per scope (Weekly/Monthly/All
					// expiries) — that scope's own single
					// highest-positive-gamma strike, via the same
					// _gamma_by_strike()-backed
					// gamma_by_strike_json/gamma_by_strike_until_json routes
					// the old checkboxes used (see refreshGammaTops below).
					// Unchecked by default.
					let SHOW_GAMMA_TOPS = false;
					// "Light"/"Dark" theme dropdown (all 3 TV chart pages — Delta
					// Chart, Gamma Chart, Strike Gamma) — see onThemeChange()/
					// applyTheme() further down. Light is the default, matching
					// this chart's original all-white look, unless the browser
					// already has a saved preference (THEME_STORAGE_KEY, a plain
					// localStorage entry — per-browser, not per-account, since
					// there's no user-settings model this addon writes to for
					// display prefs) from a previous visit, in which case that
					// preference is honored immediately (see the createChart call
					// and the select-sync block below) rather than flashing light
					// mode first. A few indicators draw their own line stroke
					// using a fixed black/gray color that would otherwise blend
					// into a black chart background — axisBlack()/rulerColor()
					// swap those to a light gray whenever dark mode is active,
					// used in place of the literal 'black'/'#555' in
					// drawGammaTopLine(), the delta=0 "supply" line color, and
					// the ruler lines.
					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function axisBlack() { return DARK_MODE ? '#e8e8e8' : '#000000'; }
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }
					// Sync the theme <select> and the body.dark CSS class to
					// whatever DARK_MODE resolved to above — the markup always
					// defaults to the "light" option server-side (there being no
					// per-user server-side setting to render it from), so a
					// returning visitor with a saved "dark" preference needs this
					// corrected client-side before anything is drawn.
					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					// "Settings" button/dialog (all 3 TV chart pages, after Ruler) —
					// user-pickable colors for the Zones boxes and Bands lines,
					// persisted per-browser via localStorage (same pattern as
					// THEME_STORAGE_KEY above), not a server-side setting. Applies
					// on every page even though Zones/Bands only ever draw data on
					// the Delta Chart (MINIMAL_CHART suppresses them elsewhere) —
					// harmless no-op there since the series just never get data.
					const COLOR_STORAGE_KEY = 'dankbit_chart_colors';
					const DEFAULT_COLORS = {
						zonesBox: '#fbc02d',
						middleZone: '#008080',
						// Keys kept as highResistance/lowSupport (not renamed to
						// smartLiqUpper/smartLiqLower) so any already-saved
						// per-browser color customization survives this change —
						// these two now feed Smart Liquidity Upper/Lower's lines,
						// not High/Resistance/Low/Support (see series creation
						// below).
						highResistance: '#2e7d32',
						lowSupport: '#c62828',
						gammaBand: '#c9a0dc',
						maxPain: '#fb8c00',
					};
					let chartColors = Object.assign({}, DEFAULT_COLORS);
					try {
						Object.assign(chartColors, JSON.parse(localStorage.getItem(COLOR_STORAGE_KEY) || '{}'));
					} catch (e) { /* malformed/legacy stored value — fall back to defaults */ }

					function hexToRgba(hex, alpha) {
						const h = hex.replace('#', '');
						const r = parseInt(h.substring(0, 2), 16);
						const g = parseInt(h.substring(2, 4), 16);
						const b = parseInt(h.substring(4, 6), 16);
						return 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
					}

					const DZ_URL           = '/api/delta-zero/' + INSTRUMENT;
					const MDZ_URL          = MONTHLY_INST ? '/api/delta-zero/' + MONTHLY_INST : '';
					const ADZ_URL          = '/api/delta-zero-all/' + ASSET;
					const DZT_URL          = '/api/delta-zero-tomorrow/' + ASSET;
					const DZT2_URL         = '/api/delta-zero-day-after-tomorrow/' + ASSET;
					const SG_URL           = '/api/gamma-by-strike/' + ASSET;
					const SGW_URL          = '/api/gamma-by-strike-until/' + INSTRUMENT;
					const SGM_URL          = MONTHLY_INST ? '/api/gamma-by-strike-until/' + MONTHLY_INST : '';
					const BANDS_URL        = '/api/bands/' + ASSET;
					const LIVE_BAND_URL    = '/api/live-band/' + ASSET;
					const ZB_URL           = '/api/zones-box/' + ASSET;
					const NEAREST_EXPIRY_URL = '/api/nearest-expiry/' + ASSET;
					const FORECAST_URL    = '/api/forecast/' + ASSET;
					// "Thales Forecast" checkbox (Delta Chart only — after
					// "Bands"; the Gamma Chart no longer has this
					// checkbox at all, so SHOW_FORECAST simply never gets
					// set true there) — unchecked by default, same server-
					// load-reducing pattern as every other optional indicator on
					// this chart.
					// Draws a fully deterministic path (see FORECAST_URL) ported
					// from Thales's own forecast-candle engine — see forecast.py.
					let SHOW_FORECAST = false;
					let   INTERVAL         = '4h';
					const klineUrl   = (iv, limit) => '/api/klines/' + ASSET + '?interval=' + iv + '&limit=' + limit;

					// Lightweight Charts has no native IANA-timezone support — it always
					// renders epoch seconds as UTC wall-clock time. To display any other
					// zone, every timestamp fed into the chart is pre-shifted by that
					// zone's current UTC offset (DST-aware, since it's computed against
					// "now"), and localization.timeFormatter below formats with
					// timeZone: 'UTC' so the shifted epoch reads as real wall-clock time.
					// The zone itself is auto-detected from the browser rather than
					// hardcoded, falling back to UTC (offset 0) if detection ever fails.
					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						// Colors already reflect DARK_MODE (a saved localStorage
						// preference from a prior visit, or the light-mode default)
						// so a returning dark-mode user doesn't see a light flash
						// before applyTheme() would otherwise run — see DARK_MODE above.
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => {
						chart.resize(window.innerWidth, window.innerHeight);
					});

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// Invisible helper series solely to extend the shared time axis
					// FUTURE_MARGIN_DAYS past the last real candle, with labeled tick
					// marks. Candlestick setData() silently drops OHLC-less
					// "whitespace" points (confirmed empirically — a 30-point future
					// whitespace array passed alongside real candles left
					// series.data().length unchanged), so a real, fully-valued (if
					// invisible) line series is used instead; all series on a chart
					// share one time scale, so its future points extend the same axis
					// the candlesticks are drawn on.
					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					const gammaBandSeries          = chart.addLineSeries({ color: chartColors.gammaBand, lineWidth: 2, lineStyle: LightweightCharts.LineStyle.Dashed, lastValueVisible: false, priceLineVisible: false });
					// Smart Role-Aware Synthetic Liquidity term-structure lines
					// (dankbit.bands.smart_liq_upper_price/smart_liq_lower_price)
					// — part of the "Bands" checkbox/refreshBands(), not a
					// separate toggle. Solid green/red, connected point-to-point —
					// this used to be where High/Resistance/Low/Support were
					// plotted (dankbit.bands.high_resistance/low_support); those
					// two fields are still computed/persisted on dankbit.bands
					// and still feed the /api/zones-box teal box and
					// dankbit.forecast.snapshot elsewhere, just no longer drawn
					// on this chart. Visible on every timeframe (1h/4h/1d), same
					// as every other Bands line — refreshBands() has no
					// timeframe gating.
					const smartLiqUpperSeries = chart.addLineSeries({ color: chartColors.highResistance, lineWidth: 2, lastValueVisible: false, priceLineVisible: false });
					const smartLiqLowerSeries = chart.addLineSeries({ color: chartColors.lowSupport, lineWidth: 2, lastValueVisible: false, priceLineVisible: false });
					// Per-hour Smart Liquidity dominance dots — same "Bands"
					// checkbox, a separate data source from the two lines above:
					// dankbit.live.band's hourly append-only log
					// (/api/live-band/<asset>), not dankbit.bands' per-instrument
					// term structure. One dot per hour/candle bucket for
					// whichever side (smart_liq_upper/smart_liq_lower) was
					// dominant that hour — deliberately NOT connected into a
					// line (transparent line color, same belt-and-suspenders
					// technique as every other dominant-point indicator in this
					// addon — lineVisible:false alone isn't enough to guarantee
					// no line renders). Same green/red as the lines above.
					const liveBandUpperSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1, lineVisible: false,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});
					const liveBandLowerSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1, lineVisible: false,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					// Zones boxes: filled rectangles marking the above-price and below-price
					// zero-crossing zones, using addBaselineSeries's flat top-line + baseValue
					// fill (the "line" is a constant top price, filled down to a constant
					// baseValue bottom price) to fake a bounded rectangle Lightweight Charts
					// has no native primitive for.
					const aboveBoxSeries = chart.addBaselineSeries({
						baseValue: { type: 'price', price: 0 },
						topLineColor: chartColors.zonesBox, topFillColor1: hexToRgba(chartColors.zonesBox, 0.25), topFillColor2: hexToRgba(chartColors.zonesBox, 0.25),
						bottomLineColor: chartColors.zonesBox, bottomFillColor1: hexToRgba(chartColors.zonesBox, 0.25), bottomFillColor2: hexToRgba(chartColors.zonesBox, 0.25),
						lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});
					const belowBoxSeries = chart.addBaselineSeries({
						baseValue: { type: 'price', price: 0 },
						topLineColor: chartColors.zonesBox, topFillColor1: hexToRgba(chartColors.zonesBox, 0.25), topFillColor2: hexToRgba(chartColors.zonesBox, 0.25),
						bottomLineColor: chartColors.zonesBox, bottomFillColor1: hexToRgba(chartColors.zonesBox, 0.25), bottomFillColor2: hexToRgba(chartColors.zonesBox, 0.25),
						lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});
					// addBaselineSeries only strokes its top edge; add a plain line series
					// for the bottom edge so both edges get the same visible border.
					const aboveBoxBottomLine = chart.addLineSeries({ color: chartColors.zonesBox, lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false });
					const belowBoxBottomLine = chart.addLineSeries({ color: chartColors.zonesBox, lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false });

					// Seller Max Profit / Buyer Max Loss box — same left/right time edges as the yellow
					// box above (both come from the same get_box() call for the nearest
					// expiry), teal so it stays visually distinct from yellow/violet/
					// green. setBoxData() already draws a single line instead of a box
					// when top and bottom coincide (or only one is available).
					const smpBmlBoxSeries = chart.addBaselineSeries({
						baseValue: { type: 'price', price: 0 },
						topLineColor: chartColors.middleZone, topFillColor1: hexToRgba(chartColors.middleZone, 0.25), topFillColor2: hexToRgba(chartColors.middleZone, 0.25),
						bottomLineColor: chartColors.middleZone, bottomFillColor1: hexToRgba(chartColors.middleZone, 0.25), bottomFillColor2: hexToRgba(chartColors.middleZone, 0.25),
						lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});
					const smpBmlBoxBottomLine = chart.addLineSeries({ color: chartColors.middleZone, lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false });

					// Thales Forecast candles ("Thales Forecast" checkbox) —
					// Thales's deterministic forecast-candle engine (see
					// forecast.py), sourced from /api/forecast/<asset>. Light
					// red/green (user-configurable, see FORECAST_UP_COLOR etc.
					// above) so it stays easily distinguishable from the real
					// candles' own teal/red at a glance.
					const forecastSeries = chart.addCandlestickSeries({
						upColor: FORECAST_UP_COLOR, downColor: FORECAST_DOWN_COLOR, borderVisible: false,
						wickUpColor: FORECAST_WICK_UP_COLOR, wickDownColor: FORECAST_WICK_DOWN_COLOR,
						lastValueVisible: false, priceLineVisible: false,
					});

					// "Top OI(s)" lines (only on /oi/<asset>, see
					// SHOW_GAMMA_POINT) — one black, lineWidth-2 price line
					// per scope (Weekly/Monthly/All expiries), marking that
					// scope's own single highest-positive-gamma strike. A
					// scope with no strikes at all, or whose highest gamma
					// is <= 0 (nothing to mark), simply contributes no
					// line. All 3 scopes reuse the same
					// _gamma_by_strike()-backed endpoints: All (SG_URL, no
					// cutoff), Weekly (SGW_URL), Monthly (SGM_URL, skipped
					// if unconfigured).
					function gammaTop(data) {
						const strikes = data.strikes || [];
						if (!strikes.length) return null;
						const top = strikes.reduce((best, item) => (item.gamma > best.gamma ? item : best), strikes[0]);
						return top.gamma > 0 ? top : null;
					}

					// Signed leg contribution, /1e6 like the combined value —
					// unlike the Abs. lines elsewhere in this addon, sign is
					// kept (not abs()'d) here since the whole point of the
					// breakdown is showing which legs pushed gamma up vs
					// down at this strike, not just how big each one is.
					function fmtLegGamma(v) {
						const r = Math.round(v / 1e6);
						return (r >= 0 ? '+' : '') + r;
					}

					function drawGammaTopLine(top, label) {
						if (!top) return;
						gammaTopsLines.push(series.createPriceLine({
							price: top.price, color: axisBlack(), lineWidth: 2,
							lineStyle: LightweightCharts.LineStyle.Solid,
							axisLabelVisible: true, axisLabelColor: axisBlack(),
							title: label + ' +' + Math.round(top.gamma / 1e6) +
								'  LC:' + fmtLegGamma(top.long_call) + ' LP:' + fmtLegGamma(top.long_put) +
								' SC:' + fmtLegGamma(top.short_call) + ' SP:' + fmtLegGamma(top.short_put),
						}));
					}

					// "Top OI(s)" checkbox (Gamma Chart only) — single
					// checkbox replacing the old separate "Strike Gamma"/
					// "Strike Gamma Nearest"/"Strike Gamma Weekly"/"Strike
					// Gamma Monthly" checkboxes; flips SHOW_GAMMA_TOPS and
					// re-fetches all 3 scopes (or clears, if just turned
					// off).
					// Re-checked between every awaited fetch below (see each
					// `if (gammaTopsOff())` call) — the checkbox may get switched
					// off mid-sequence, since this function chains 3 sequential
					// fetches; without re-checking, a toggle-off partway through
					// would still let the remaining fetches draw their lines a few
					// seconds later. On a mid-sequence bail, clears whatever this
					// run had already drawn so far too, not just skips new lines.
					function gammaTopsOff() { return !SHOW_GAMMA_POINT || !SHOW_GAMMA_TOPS; }

					async function refreshGammaTops() {
						// Re-entrancy guard (see gammaTopsRefreshing's own comment) —
						// a call that finds one already in flight just skips this
						// tick entirely rather than racing it; the next poll or
						// toggle will pick up fresh data anyway.
						if (gammaTopsRefreshing) return;
						gammaTopsRefreshing = true;
						try {
							gammaTopsLines.forEach(l => series.removePriceLine(l));
							gammaTopsLines.length = 0;
							if (gammaTopsOff()) return;

							const allData = await (await fetch(SG_URL)).json();
							if (gammaTopsOff()) return;
							drawGammaTopLine(gammaTop(allData), 'All');

							const weeklyData = await (await fetch(SGW_URL)).json();
							if (gammaTopsOff()) { gammaTopsLines.forEach(l => series.removePriceLine(l)); gammaTopsLines.length = 0; return; }
							drawGammaTopLine(gammaTop(weeklyData), 'Weekly');

							if (SGM_URL) {
								const monthlyData = await (await fetch(SGM_URL)).json();
								if (gammaTopsOff()) { gammaTopsLines.forEach(l => series.removePriceLine(l)); gammaTopsLines.length = 0; return; }
								drawGammaTopLine(gammaTop(monthlyData), 'Monthly');
							}
						} finally {
							gammaTopsRefreshing = false;
						}
					}

					function onToggleGammaTops() {
						SHOW_GAMMA_TOPS = document.getElementById('gamma-tops-toggle').checked;
						refreshGammaTops();
					}

					// "Strike Gamma" lines (/mp/<instrument> only) — the
					// restored per-strike indicator: one price line per
					// distinct strike that has ever traded, isolated to
					// STRIKE_GAMMA_INSTRUMENT's own expiry alone (see SGI_URL
					// — gamma-by-strike-at, not the cumulative
					// gamma-by-strike-until Top OI(s) uses), unlike Gamma
					// Tops' single top-strike-per-scope line. Color is a
					// light-gray-to-black gradient by
					// |gamma| magnitude relative to the largest |gamma| in
					// this same response — the strike with the biggest
					// exposure is always pure black, the smallest is light
					// gray. Title is signed dollar-gamma (abs/1e6, rounded,
					// '+' for net buy-side/taker-dominant, '-' for net
					// sell-side, same raw buy/sell convention every other
					// Buyer/Seller-labeled line in this app uses), followed
					// by that strike's own dominant leg — whichever of
					// long_call/long_put/short_call/short_put has the
					// largest |value| at that strike (same 4-leg split
					// options.per_leg_greeks()/Top OI(s) use), labeled
					// LC/LP/SC/SP — so a glance at the line says not just
					// how much gamma is at this strike but which position
					// is driving it.
					let strikeGammaLines = [];
					// Max Pain (/mp/<instrument> only, alongside Strike
					// Gamma above) — the strike where Deribit's real open
					// interest, not dankbit's own recorded trades (see
					// ChartController._max_pain_for_expiry), would pay out
					// the least total intrinsic value to option holders
					// across the whole chain if settled there. A single
					// reference level, so — unlike the per-strike gamma
					// lines above, which are axis-label-only
					// (lineVisible: false) — this one draws a real visible
					// line.
					let maxPainLine = null;

					function dominantLeg(item) {
						const legs = { LC: item.long_call, LP: item.long_put, SC: item.short_call, SP: item.short_put };
						return Object.keys(legs).reduce((best, k) => Math.abs(legs[k]) > Math.abs(legs[best]) ? k : best, 'LC');
					}

					function drawStrikeGammaLines(data) {
						strikeGammaLines.forEach(l => series.removePriceLine(l));
						strikeGammaLines.length = 0;
						if (maxPainLine) { series.removePriceLine(maxPainLine); maxPainLine = null; }
						const strikes = data.strikes || [];
						const maxAbsGamma = strikes.reduce((m, item) => Math.max(m, Math.abs(item.gamma)), 0);
						strikes.forEach(item => {
							const sign = item.gamma >= 0 ? '+' : '-';
							const intensity = maxAbsGamma > 0 ? Math.abs(item.gamma) / maxAbsGamma : 0;
							// Light mode: biggest exposure -> near-black (high contrast
							// on white), smallest -> light gray, as before. Dark mode
							// mirrors that same gradient (255 - lightShade) so the
							// biggest exposure instead lands near-white (high contrast
							// on black) rather than vanishing into it.
							const lightShade = Math.round(220 - intensity * 220);
							const shade = DARK_MODE ? 255 - lightShade : lightShade;
							const color = 'rgb(' + shade + ',' + shade + ',' + shade + ')';
							strikeGammaLines.push(series.createPriceLine({
								price: item.price, color, lineWidth: 1, lineVisible: false,
								lineStyle: LightweightCharts.LineStyle.Solid,
								axisLabelVisible: true, axisLabelColor: color,
								title: 'Γ ' + sign + Math.round(Math.abs(item.gamma) / 1e6) + ' ' + dominantLeg(item),
							}));
						});

						// 0/null means no open interest at all for this expiry
						// (see options.max_pain) — same "falsy means absent"
						// convention every other price-level field in this
						// addon uses, so no line is drawn rather than a
						// spurious price-0 one.
						if (data.max_pain) {
							maxPainLine = series.createPriceLine({
								price: data.max_pain, color: chartColors.maxPain, lineWidth: 2,
								lineStyle: LightweightCharts.LineStyle.Solid,
								axisLabelVisible: true, axisLabelColor: chartColors.maxPain,
								title: 'Max Pain',
							});
						}
					}

					// No checkbox — this is /mp/<instrument>'s sole
					// purpose, so it's always on (gated only by
					// SHOW_STRIKE_GAMMA/SGI_URL themselves being set at all,
					// same as every other minimal-page indicator's
					// MINIMAL_CHART gating elsewhere on this page).
					async function refreshStrikeGamma() {
						if (!SHOW_STRIKE_GAMMA || !SGI_URL) return;
						const data = await (await fetch(SGI_URL)).json();
						drawStrikeGammaLines(data);
					}

					let priceLines    = [];
					let monthlyLines  = [];
					let allLines      = [];
					let tomorrowLines = [];
					let dayAfterTomorrowLines = [];

					function clearLines(arr) {
						arr.forEach(pl => series.removePriceLine(pl));
						arr.length = 0;
					}
					// Gamma Chart's own "Top OI(s)" line set (see
					// refreshGammaTops above) — the Delta Chart has no
					// gamma peak/bottom line indicator of its own; that
					// indicator lives only on the Gamma Chart.
					let gammaTopsLines = [];
					// refreshGammaTops does 3 sequential awaited fetches, and is
					// itself called from init(), the checkbox's onToggleGammaTops(),
					// and setInterval(refreshGammaTops, REFRESH) — without this
					// guard, an overlapping invocation (e.g. a poll tick firing
					// while a previous run is still mid-flight) races on the
					// shared gammaTopsLines array: each clears what the other
					// already drew and pushes its own lines on top, leaving
					// duplicated/orphaned price lines behind.
					let gammaTopsRefreshing = false;

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					const TF_WINDOW = { '1h': 30, '4h': 15, '1d': 365 };
					const BARS_PER_DAY = { '1h': 24, '4h': 6, '1d': 1 };
					const INTERVAL_SECONDS = { '1h': 3600, '4h': 4 * 3600, '1d': 86400 };

					const FUTURE_MARGIN_DAYS = 5;

					// realCandles.length + futureTickCount is the current total
					// logical bar count across both series sharing the time axis —
					// tracked directly rather than re-derived from series.data(),
					// since the candlestick series' own data() only ever reflects
					// realCandles (see futureAxisSeries above).
					let realCandles = [];
					let futureTickCount = 0;

					function applyVisibleRange() {
						const days = TF_WINDOW[INTERVAL] || 21;
						const barsPerDay = BARS_PER_DAY[INTERVAL] || 24;
						const lastIndex = realCandles.length + futureTickCount - 1;
						chart.timeScale().setVisibleLogicalRange({
							from: lastIndex - days * barsPerDay,
							to:   lastIndex,
						});
					}

					// Right-click "Reset chart view" — mirrors original TradingView's
					// context-menu item: re-autoscales the price axis (undoes any
					// manual drag-zoom on the price scale) and restores the default
					// time-scale window for the current timeframe (undoes any
					// pan/zoom on the time axis), without touching series data or any
					// indicator toggle state.
					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					// Custom context menu (Lightweight Charts has no built-in one) —
					// right-clicking the chart area shows a single "Reset chart view"
					// item at the cursor, clamped so it never renders off-screen.
					const contextMenu = document.getElementById('context-menu');

					function hideContextMenu() {
						contextMenu.style.display = 'none';
					}

					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}

					function onResetChartViewClick() {
						resetChartView();
						hideContextMenu();
					}

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => {
						e.preventDefault();
						showContextMenu(e.clientX, e.clientY);
					});
					// Right-clicking outside the chart area (e.g. the toolbar) falls
					// through to the browser's own native context menu — hide ours
					// first so it doesn't linger open underneath it.
					document.addEventListener('contextmenu', e => {
						if (!chartContainerEl.contains(e.target)) hideContextMenu();
					});
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					function rebuildSeriesData() {
						series.setData(realCandles);

						const intervalSec = INTERVAL_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = Math.round(FUTURE_MARGIN_DAYS * 86400 / intervalSec);
						const futureTicks = [];
						for (let i = 1; i <= count; i++) {
							futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						}
						futureTickCount = futureTicks.length;
						futureAxisSeries.setData(futureTicks);
					}

					async function loadCandles() {
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						rebuildSeriesData();
						applyVisibleRange();
					}

					async function updateLatestCandle() {
						const resp = await (await fetch(klineUrl(INTERVAL, 2))).json();
						const klines = resp.result || [];
						if (!klines.length) return;
						const updated = toCandle(klines[0]);
						if (realCandles.length && realCandles[realCandles.length - 1].time === updated.time) {
							realCandles[realCandles.length - 1] = updated;
						} else {
							realCandles.push(updated);
						}
						rebuildSeriesData();
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
						await refreshBands();
						await refreshLiveBandDots();
						await refreshZonesBoxes();
						await updateForecastVisibility();
					}

					async function refreshDeltaZero() {
						if (MINIMAL_CHART || !SHOW_ALL_LINES) return;
						const data = await (await fetch(DZ_URL)).json();
						// Re-check: "S/D" may have been switched off while this fetch
						// was in flight — onToggleLines() already cleared priceLines
						// synchronously in that case, so just bail without redrawing.
						if (!SHOW_ALL_LINES) return;
						clearLines(priceLines);
						if (!SHOW_WEEKLY_LINES) return;
						const zeros = [...(data.delta_zero || [])].sort((a, b) => a.price - b.price);
						zeros.forEach(item => priceLines.push(series.createPriceLine({
							price: item.price, color: item.type === 'demand' ? 'red' : axisBlack(), lineWidth: 1,
							lineStyle: LightweightCharts.LineStyle.Solid,
							axisLabelVisible: true, axisLabelColor: axisBlack(), title: 'Weekly',
						})));
					}

					let nearestExpiryStr = null;
					let lastTradeCount = 0;

					function updateStatusLine() {
						const expiries = [INSTRUMENT, MONTHLY_INST].filter(Boolean).join('  ·  ');
						let text = expiries + '  ·  ' + lastTradeCount + ' trades';
						if (nearestExpiryStr) text += '  ·  Nearest: ' + nearestExpiryStr;
						setStatus(text);
					}

					async function refreshMonthlyDeltaZero() {
						if (!MDZ_URL) return;
						const data = await (await fetch(MDZ_URL)).json();
						clearLines(monthlyLines);
						// Line drawing is skipped in minimal mode or with the "S/D"
						// checkbox off, but this fetch still runs — its trade_count
						// feeds the footer's "N trades", which stays on /oi/<asset> too.
						if (SHOW_MONTHLY_LINES && !MINIMAL_CHART && SHOW_ALL_LINES) {
							const zeros = [...(data.delta_zero || [])].sort((a, b) => a.price - b.price);
							zeros.forEach(item => monthlyLines.push(series.createPriceLine({
								price: item.price, color: item.type === 'demand' ? 'red' : axisBlack(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Solid,
								axisLabelVisible: true, axisLabelColor: axisBlack(), title: 'Monthly',
							})));
						}
						lastTradeCount = data.trade_count || 0;
						updateStatusLine();
					}

					async function refreshNearestExpiry() {
						// Cheap standalone lookup (no curve-building) — the yellow zones
						// boxes use this same nearest-active-expiry internally, but via
						// their own full computation, not this lightweight endpoint.
						const data = await (await fetch(NEAREST_EXPIRY_URL)).json();
						nearestExpiryStr = data.expiry || null;
						updateStatusLine();
					}

					async function refreshAllDeltaZero() {
						if (MINIMAL_CHART || !SHOW_ALL_LINES) return;
						const data = await (await fetch(ADZ_URL)).json();
						// Re-check: see refreshDeltaZero's own comment above.
						if (!SHOW_ALL_LINES) return;
						clearLines(allLines);
						const zeros = [...(data.delta_zero || [])].sort((a, b) => a.price - b.price);
						zeros.forEach(item => allLines.push(series.createPriceLine({
							price: item.price, color: item.type === 'demand' ? 'red' : axisBlack(), lineWidth: 1,
							lineStyle: LightweightCharts.LineStyle.Solid,
							axisLabelVisible: true, axisLabelColor: axisBlack(), title: 'All',
						})));
					}

					async function refreshTomorrowDeltaZero() {
						if (MINIMAL_CHART || !SHOW_ALL_LINES) return;
						const data = await (await fetch(DZT_URL)).json();
						// Re-check: see refreshDeltaZero's own comment above.
						if (!SHOW_ALL_LINES) return;
						clearLines(tomorrowLines);
						if (!SHOW_DAILY_LINES) return;
						const zeros = [...(data.delta_zero || [])].sort((a, b) => a.price - b.price);
						zeros.forEach(item => tomorrowLines.push(series.createPriceLine({
							price: item.price, color: item.type === 'demand' ? 'red' : axisBlack(), lineWidth: 1,
							lineStyle: LightweightCharts.LineStyle.Solid,
							axisLabelVisible: true, axisLabelColor: 'orange', title: 'Daily (24H)',
						})));
					}

					async function refreshDayAfterTomorrowDeltaZero() {
						if (MINIMAL_CHART || !SHOW_ALL_LINES) return;
						const data = await (await fetch(DZT2_URL)).json();
						// Re-check: see refreshDeltaZero's own comment above.
						if (!SHOW_ALL_LINES) return;
						clearLines(dayAfterTomorrowLines);
						if (!SHOW_DAILY_LINES) return;
						const zeros = [...(data.delta_zero || [])].sort((a, b) => a.price - b.price);
						zeros.forEach(item => dayAfterTomorrowLines.push(series.createPriceLine({
							price: item.price, color: item.type === 'demand' ? 'red' : axisBlack(), lineWidth: 1,
							lineStyle: LightweightCharts.LineStyle.Solid,
							axisLabelVisible: true, axisLabelColor: 'orange', title: 'Daily+1 (24H)',
						})));
					}

					// "S/D" checkbox (next to Ruler) — hides every horizontal
					// price-line indicator (delta=0 sets) and stops their
					// refresh*() functions from even fetching (see SHOW_ALL_LINES
					// above), to actually cut server load rather than just hiding
					// the result. Turning off clears everything immediately rather
					// than waiting for each set's own next poll (their refresh*()
					// functions return before their own clearLines() call when
					// SHOW_ALL_LINES is false). Turning back on re-fetches
					// everything immediately for the same reason.
					// refreshMonthlyDeltaZero() is untouched here — it always
					// keeps polling regardless, for the footer's trade count.
					function onToggleLines() {
						SHOW_ALL_LINES = document.getElementById('lines-toggle').checked;
						if (SHOW_ALL_LINES) {
							refreshDeltaZero();
							refreshMonthlyDeltaZero();
							refreshAllDeltaZero();
							refreshTomorrowDeltaZero();
							refreshDayAfterTomorrowDeltaZero();
						} else {
							clearLines(priceLines);
							clearLines(monthlyLines);
							clearLines(allLines);
							clearLines(tomorrowLines);
							clearLines(dayAfterTomorrowLines);
						}
					}

					// Populated by refreshBands() from the same rows that feed
					// smartLiqUpperSeries/smartLiqLowerSeries (the green/red
					// Smart Liquidity term-structure lines), kept around so
					// refreshLiveBandDots() can snap each hourly dominance dot
					// onto that same line instead of its own real price — see
					// interpolateOnLine() below. The lines' own data/rendering
					// is untouched by this; these are read-only copies.
					let smartLiqUpperPoints = [];
					let smartLiqLowerPoints = [];

					function clearBandsLines() {
						smartLiqUpperSeries.setData([]);
						smartLiqLowerSeries.setData([]);
						smartLiqUpperSeries.setMarkers([]);
						smartLiqLowerSeries.setMarkers([]);
						smartLiqUpperPoints = [];
						smartLiqLowerPoints = [];
						gammaBandSeries.setData([]);
						liveBandUpperSeries.setData([]);
						liveBandLowerSeries.setData([]);
						liveBandUpperSeries.setMarkers([]);
						liveBandLowerSeries.setMarkers([]);
					}

					// Value of a sparse, time-sorted {time, value} line at an
					// arbitrary time, linearly interpolated between its two
					// bracketing points. Clamped to the first/last value when
					// time falls outside the line's own range — in practice
					// every hourly dominance dot's time is well before the
					// Smart Liquidity line's own points (each positioned at a
					// tracked expiry's future settlement time — see
					// dankbit.bands), so this clamps every dot to the nearest
					// (current) expiry's level rather than extrapolating.
					// null with no points at all (line not loaded/absent yet).
					function interpolateOnLine(points, time) {
						if (!points.length) return null;
						if (time <= points[0].time) return points[0].value;
						if (time >= points[points.length - 1].time) return points[points.length - 1].value;
						for (let i = 0; i < points.length - 1; i++) {
							const a = points[i], b = points[i + 1];
							if (time >= a.time && time <= b.time) {
								const frac = (time - a.time) / (b.time - a.time);
								return a.value + frac * (b.value - a.value);
							}
						}
						return points[points.length - 1].value;
					}

					async function refreshBands() {
						if (MINIMAL_CHART || !SHOW_BANDS) return;
						const data = await (await fetch(BANDS_URL)).json();
						// Re-check: "Bands" may have been switched off while this fetch
						// was in flight — onToggleBands() already cleared everything
						// synchronously in that case, so just bail without redrawing.
						if (!SHOW_BANDS) return;
						const rows = data.bands || [];
						gammaBandSeries.setData(rows.map(r => ({ time: Math.floor(r.t / 1000) + tzOffset, value: r.gamma_band })));
						// 0.0 means absent (see dankbit.bands' smart_liq_upper_price/
						// smart_liq_lower_price) — filtered out rather than plotted,
						// same principle setBoxData()'s "0.0 = no crossing" already
						// applies to the zones boxes, so a legless/degenerate point
						// doesn't render as a spurious price-0 dip in the line.
						const smartLiqUpperRows = rows.filter(r => r.smart_liq_upper_price);
						const smartLiqLowerRows = rows.filter(r => r.smart_liq_lower_price);
						smartLiqUpperPoints = smartLiqUpperRows.map(r => ({ time: Math.floor(r.t / 1000) + tzOffset, value: r.smart_liq_upper_price }));
						smartLiqLowerPoints = smartLiqLowerRows.map(r => ({ time: Math.floor(r.t / 1000) + tzOffset, value: r.smart_liq_lower_price }));
						smartLiqUpperSeries.setData(smartLiqUpperPoints);
						smartLiqLowerSeries.setData(smartLiqLowerPoints);

						// Per-point marker on each future expiry point: size is
						// the dominance dot restored from before the Bands
						// rework (a visible circle, size 1, wherever that
						// side's own smart_liq_upper_strength/
						// smart_liq_lower_strength beats its counterpart at
						// that SAME expiry — dominance can flip from one
						// tracked expiry to the next, so each point is
						// compared only against itself; size 0/invisible
						// otherwise), text is the +/- marker (whether the
						// payoff at that High/Resistance or Low/Support
						// intersection sits above or below the zero-payoff
						// line) restored alongside it — both re-attached to
						// the Smart Liquidity lines since High/Resistance/
						// Low/Support no longer have their own line series on
						// this chart. position:'inBar' keeps the dot centered
						// on the line's own value so it reads as a normal
						// point sitting on the line. Scoped to
						// smartLiqUpperRows/smartLiqLowerRows (not the full
						// rows list) since a marker's time must match an
						// existing data point on that series.
						smartLiqUpperSeries.setMarkers(smartLiqUpperRows.map(r => ({
							time: Math.floor(r.t / 1000) + tzOffset,
							position: 'inBar',
							color: chartColors.highResistance,
							shape: 'circle',
							size: r.smart_liq_upper_strength > r.smart_liq_lower_strength ? 1 : 0,
							text: r.high_resistance_positive ? '+' : '-',
						})));
						smartLiqLowerSeries.setMarkers(smartLiqLowerRows.map(r => ({
							time: Math.floor(r.t / 1000) + tzOffset,
							position: 'inBar',
							color: chartColors.lowSupport,
							shape: 'circle',
							size: r.smart_liq_lower_strength > r.smart_liq_upper_strength ? 1 : 0,
							text: r.low_support_positive ? '+' : '-',
						})));
					}

					// Live Band rows are computed hourly, but a dot must land on
					// whatever candle width is currently selected — collapses
					// multiple hourly rows into one per bucket of the CURRENT
					// timeframe (the later row wins on a collision), same
					// technique the old /z/<asset> page's own bucketTime() used.
					function liveBandBucketTime(epochMs) {
						const rawSeconds = Math.floor(epochMs / 1000);
						const bucket = INTERVAL_SECONDS[INTERVAL] || 3600;
						return Math.floor(rawSeconds / bucket) * bucket + tzOffset;
					}

					// Part of the "Bands" checkbox (SHOW_BANDS) — one dot per
					// hour/candle bucket for whichever side of
					// dankbit.live.band's smart_liq_upper/smart_liq_lower was
					// dominant that hour, via smart_liq_upper_strength/
					// smart_liq_lower_strength (not the raw prices — upper is,
					// by construction, always a higher price than lower, so
					// comparing prices would always pick "upper"). Read-only —
					// never triggers a new dankbit.live.band row; only that
					// model's own hourly cron does.
					async function refreshLiveBandDots() {
						if (MINIMAL_CHART || !SHOW_BANDS) return;
						const data = await (await fetch(LIVE_BAND_URL)).json();
						if (!SHOW_BANDS) return;
						const rawPoints = data.points || [];
						const byBucket = new Map();
						rawPoints.forEach(p => byBucket.set(liveBandBucketTime(p.t), p));
						const points = Array.from(byBucket.keys())
							.sort((a, b) => a - b)
							.map(time => Object.assign({ time }, byBucket.get(time)));

						const upperDominant = [];
						const lowerDominant = [];
						points.forEach(p => {
							const hasUpper = !!p.smart_liq_upper;
							const hasLower = !!p.smart_liq_lower;
							if (!hasUpper && !hasLower) return;
							let upperWins = false, lowerWins = false;
							if (hasUpper && hasLower) {
								if (p.smart_liq_upper_strength > p.smart_liq_lower_strength) upperWins = true;
								else if (p.smart_liq_lower_strength > p.smart_liq_upper_strength) lowerWins = true;
							} else if (hasUpper) {
								upperWins = true;
							} else {
								lowerWins = true;
							}
							// Plotted position is snapped onto the green/red Smart
							// Liquidity line itself (via interpolateOnLine()) rather
							// than this dot's own real smart_liq_upper/lower price —
							// a display-only change for a cleaner chart; the
							// dominance decision above (upperWins/lowerWins) and
							// every other calculation are untouched. Skipped if
							// that line has no points loaded at all. realPrice (the
							// actual smart_liq_upper/lower value, not the on-line
							// plotted position) is kept alongside so the "current"
							// point below can still label its true price.
							if (upperWins) {
								const v = interpolateOnLine(smartLiqUpperPoints, p.time);
								if (v !== null) upperDominant.push({ time: p.time, value: v, realPrice: p.smart_liq_upper });
							}
							if (lowerWins) {
								const v = interpolateOnLine(smartLiqLowerPoints, p.time);
								if (v !== null) lowerDominant.push({ time: p.time, value: v, realPrice: p.smart_liq_lower });
							}
						});
						liveBandUpperSeries.setData(upperDominant.map(p => ({ time: p.time, value: p.value })));
						liveBandLowerSeries.setData(lowerDominant.map(p => ({ time: p.time, value: p.value })));

						// Only the single most-recent hourly dot (today's/now's
						// dominant side, whichever bucket is latest across both
						// series) gets a text label of its real Smart Liquidity
						// price — every older hourly dot keeps its plain circle
						// with no text, and the green/red line's own (future)
						// term-structure points are untouched entirely. Drawn via
						// the marker's own "text" (on the chart body, next to the
						// point), never the axis label, so it can't land on the
						// price panel.
						const latestUpper = upperDominant.length ? upperDominant[upperDominant.length - 1] : null;
						const latestLower = lowerDominant.length ? lowerDominant[lowerDominant.length - 1] : null;
						let currentSide = null;
						if (latestUpper && latestLower) currentSide = latestUpper.time >= latestLower.time ? 'upper' : 'lower';
						else if (latestUpper) currentSide = 'upper';
						else if (latestLower) currentSide = 'lower';

						function liveBandMarker(p, color, isCurrent) {
							const marker = { time: p.time, position: 'inBar', color, shape: 'circle', size: 1 };
							// Lightweight Charts has no horizontal marker-text
							// offset — text is centered on the marker's own time
							// position — so leading spaces are used to push the
							// (still-centered) text visually off to the right of
							// the point instead of straddling it.
							if (isCurrent) marker.text = '      ' + String(Math.round(p.realPrice));
							return marker;
						}
						liveBandUpperSeries.setMarkers(
							upperDominant.map(p => liveBandMarker(p, chartColors.highResistance, currentSide === 'upper' && p.time === latestUpper.time))
						);
						liveBandLowerSeries.setMarkers(
							lowerDominant.map(p => liveBandMarker(p, chartColors.lowSupport, currentSide === 'lower' && p.time === latestLower.time))
						);
					}

					function setBoxData(boxSeries, bottomLineSeries, top, bottom, fromTime, toTime) {
						// 0.0 is the "no crossing at all" sentinel (see
						// dankbit.bands) — nothing real to draw on that edge.
						if (!top && !bottom) { boxSeries.setData([]); bottomLineSeries.setData([]); return; }
						if (top && bottom && top !== bottom) {
							boxSeries.applyOptions({ baseValue: { type: 'price', price: bottom } });
							boxSeries.setData([
								{ time: fromTime, value: top },
								{ time: toTime, value: top },
							]);
							bottomLineSeries.setData([
								{ time: fromTime, value: bottom },
								{ time: toTime, value: bottom },
							]);
							return;
						}
						// Only one edge has a crossing, or both coincide (zero-height
						// box) — can't draw a rectangle, so draw a single line at
						// whichever price we do have instead of dropping it silently.
						const price = top || bottom;
						boxSeries.setData([]);
						bottomLineSeries.setData([
							{ time: fromTime, value: price },
							{ time: toTime, value: price },
						]);
					}

					function clearZonesBoxes() {
						aboveBoxSeries.setData([]);
						belowBoxSeries.setData([]);
						aboveBoxBottomLine.setData([]);
						belowBoxBottomLine.setData([]);
						smpBmlBoxSeries.setData([]);
						smpBmlBoxBottomLine.setData([]);
					}

					async function refreshZonesBoxes() {
						if (MINIMAL_CHART || !SHOW_ZONES_BOXES) return;
						// Live lookup — computed fresh by the server on every call (see
						// dankbit.bands.get_box), not read from stored history.
						// Persisted (feeding the Bands lines' history) unless
						// ZONES_BOX_WINDOW_MODE is 'hours', in which case the ?hours=
						// override makes the server compute display-only instead — see
						// ZONES_BOX_WINDOW_MODE above.
						const url = ZONES_BOX_WINDOW_MODE === 'hours'
							? ZB_URL + '?hours=' + ZONES_BOX_WINDOW_HOURS
							: ZB_URL;
						const data = await (await fetch(url)).json();
						// Re-check: the "Zones" checkbox may have been switched off
						// while this fetch was in flight (e.g. a periodic poll or a
						// timeframe switch) — the guard at the top of this function
						// only ran before the request started, so without this the
						// boxes would still get redrawn a few seconds after being
						// unchecked once this stale response arrives.
						if (!SHOW_ZONES_BOXES) return;
						if (!data || data.t === undefined) {
							clearZonesBoxes();
							return;
						}
						const fromTime = Math.floor(Date.now() / 1000) + tzOffset - 10 * 86400;
						const toTime   = Math.floor(data.expiration / 1000) + tzOffset;

						const aboveTop    = Math.max(data.short_zero_above_price, data.long_zero_above_price);
						const aboveBottom = Math.min(data.short_zero_above_price, data.long_zero_above_price);
						setBoxData(aboveBoxSeries, aboveBoxBottomLine, aboveTop, aboveBottom, fromTime, toTime);

						const belowTop    = Math.max(data.short_zero_below_price, data.long_zero_below_price);
						const belowBottom = Math.min(data.short_zero_below_price, data.long_zero_below_price);
						setBoxData(belowBoxSeries, belowBoxBottomLine, belowTop, belowBottom, fromTime, toTime);

						// Seller Max Profit / Buyer Max Loss box — same fromTime/toTime as the yellow box
						// above, since both come from this same nearest-expiry get_box() call.
						const smpBmlTop    = Math.max(data.seller_max_profit, data.buyer_max_loss);
						const smpBmlBottom = Math.min(data.seller_max_profit, data.buyer_max_loss);
						setBoxData(smpBmlBoxSeries, smpBmlBoxBottomLine, smpBmlTop, smpBmlBottom, fromTime, toTime);
					}

					// "Zones" checkbox (Delta Chart only, right after "S/D") —
					// controls the yellow High Zone/Low Zone boxes and the teal
					// Middle Zone (Seller Max Profit/Buyer Max Loss) box, i.e.
					// everything refreshZonesBoxes()/clearZonesBoxes() draw.
					// Checked by default (SHOW_ZONES_BOXES starts true, matching
					// the checkbox's own default-checked state), since these boxes
					// were always shown before this checkbox existed. Stops
					// refreshZonesBoxes() from calling the server at all while off
					// (see SHOW_ZONES_BOXES above), purely to reduce server load —
					// not just hiding the result; get_box() never persists to
					// dankbit.bands regardless, so this has no effect on that
					// model either way. The 4-hourly compute_snapshot() cron is
					// untouched either way. Clears the boxes immediately
					// when switched off and re-fetches immediately when switched
					// back on.
					function onToggleZonesBoxes() {
						SHOW_ZONES_BOXES = document.getElementById('zones-boxes-toggle').checked;
						if (SHOW_ZONES_BOXES) {
							refreshZonesBoxes();
						} else {
							clearZonesBoxes();
						}
					}

					// "Bands" checkbox (Delta Chart only, next to "Zones") —
					// controls only the High/Resistance + Low/Support + Gamma Band lines
					// (green/red/dashed violet), NOT the yellow/teal zones boxes,
					// which have their own separate "Zones" checkbox instead
					// (SHOW_ZONES_BOXES/onToggleZonesBoxes() above). refreshBands()
					// only ever reads the already-persisted dankbit.bands rows
					// (/api/bands/<asset>) — it never triggers a new computation.
					// Those rows are kept fresh solely by the 4-hourly compute_snapshot()
					// cron; toggling this checkbox, or this browser polling it, has no
					// effect on when new extrema get computed. Clears the lines
					// immediately when switched off (refreshBands() returns
					// before clearing when SHOW_BANDS is false) and re-fetches
					// immediately when switched back on.
					function onToggleBands() {
						SHOW_BANDS = document.getElementById('bands-toggle').checked;
						if (SHOW_BANDS) {
							// Sequenced (not fired in parallel) — refreshLiveBandDots()
							// now reads smartLiqUpperPoints/smartLiqLowerPoints, which
							// only refreshBands() populates.
							refreshBands().then(refreshLiveBandDots);
						} else {
							clearBandsLines();
						}
					}

					function clearForecastLines() {
						forecastSeries.setData([]);
					}

					// The Thales Forecast candles are 4h resolution and only
					// make visual sense lined up against real 4h-spaced
					// candles, so both the checkbox and the series itself
					// are restricted to the 4h timeframe — shown/hidden by
					// updateForecastVisibility() on every timeframe switch.
					// Called from setTf()/init() on both Delta and Gamma
					// Chart (both share setTf()), but the checkbox itself
					// only exists on the Delta Chart — guarded with a null
					// check rather than assuming the element is present.
					function updateForecastVisibility() {
						const visible = INTERVAL === '4h';
						const wrap = document.getElementById('forecast-toggle-wrap');
						if (wrap) wrap.style.display = visible ? '' : 'none';
						refreshForecast();
					}

					// "Thales Forecast" checkbox (Delta Chart only) —
					// fetches /api/forecast/<asset> and draws the forecast
					// candles (see FORECAST_URL, forecastSeries above). Stops
					// fetching entirely while off, or while not on the 4h
					// timeframe (see updateForecastVisibility above), same
					// server-load-reducing pattern as every other optional
					// indicator here. Display time is NOT taken from the
					// server's `t` (an arbitrary now-relative timestamp) — it's
					// recomputed here, anchored to the same grid
					// futureAxisSeries uses for its own future ticks
					// (realCandles[last].time, stepped by intervalSec).
					// Lightweight Charts builds one shared logical time axis
					// from the union of every series' timestamps; server-
					// relative "now" timestamps almost never land on that grid,
					// so forecastSeries' points ended up alternating with
					// futureAxisSeries' ticks in the same stretch — each series
					// only getting every other logical slot, which rendered as
					// every other forecast candle missing.
					//
					// The anchor walks forward from realCandles[last].time
					// (a whole number of intervalSec steps at a time, so it
					// never leaves the grid) until it's strictly past "now"
					// — rather than assuming realCandles[last] is always
					// the current still-forming candle (one step behind
					// "now"), which would silently break if Deribit or the
					// 5s updateLatestCandle() poll ever returned a stale
					// last-closed candle instead. This guarantees the first
					// forecast candle is always the next 4h candle after
					// now, on the correct grid, regardless of which one
					// realCandles[last] actually is.
					async function refreshForecast() {
						if (!SHOW_FORECAST || INTERVAL !== '4h' || !realCandles.length) { clearForecastLines(); return; }
						const data = await (await fetch(FORECAST_URL)).json();
						// Re-check: "Thales Forecast" may have been switched off (or the
						// timeframe changed away from 4h) while this fetch was in
						// flight — onToggleForecast() already cleared the series
						// synchronously in that case, so just bail without redrawing.
						if (!SHOW_FORECAST || INTERVAL !== '4h') return;
						const points = data.points || [];
						if (!points.length) { clearForecastLines(); return; }
						const intervalSec = INTERVAL_SECONDS[INTERVAL];
						const nowShifted = Math.floor(Date.now() / 1000) + tzOffset;
						let firstTime = realCandles[realCandles.length - 1].time;
						while (firstTime <= nowShifted) firstTime += intervalSec;
						forecastSeries.setData(points.map((p, i) => ({
							time: firstTime + i * intervalSec,
							open: p.open, high: p.high, low: p.low, close: p.close,
						})));
					}

					function onToggleForecast() {
						SHOW_FORECAST = document.getElementById('forecast-toggle').checked;
						if (SHOW_FORECAST) {
							refreshForecast();
						} else {
							clearForecastLines();
						}
					}

					// "Zones from" dropdown — 00:00-Iran-vs-trailing-hours window for
					// the zones boxes (see ZONES_BOX_WINDOW_MODE above) — re-fetches
					// immediately on change rather than waiting for the next
					// ZONES_BOX_REFRESH poll.
					function onZonesBoxWindowChange() {
						ZONES_BOX_WINDOW_MODE = document.getElementById('zones-box-window-select').value;
						refreshZonesBoxes();
					}

					// "Light"/"Dark" radio (see DARK_MODE/axisBlack()/rulerColor()
					// above) — swaps the chart's own canvas-drawn colors via
					// chart.applyOptions() and toggles body.dark for the fixed HTML
					// overlays (status bar, toggle labels, exchange label, ruler
					// info, context menu — see the <style> block). Candle/box/band
					// series already use saturated colors that read fine on either
					// background, so only the chart chrome needs swapping here.
					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
						// Re-invoke every indicator whose own line stroke color is
						// theme-dependent (axisBlack()) so the switch takes effect
						// immediately instead of waiting for the next poll — each
						// already no-ops (or has already cleared its own lines) if
						// that indicator isn't currently shown/enabled.
						refreshDeltaZero();
						refreshMonthlyDeltaZero();
						refreshAllDeltaZero();
						refreshTomorrowDeltaZero();
						refreshDayAfterTomorrowDeltaZero();
						refreshGammaTops();
						refreshStrikeGamma();
					}

					// "Settings" button/dialog (after Ruler, all 3 TV chart pages) —
					// re-applies the current chartColors to every already-created
					// series/line via applyOptions() rather than needing a
					// server round-trip or a full chart rebuild.
					function applyChartColors() {
						const c = chartColors;
						const zonesRgba = hexToRgba(c.zonesBox, 0.25);
						aboveBoxSeries.applyOptions({ topLineColor: c.zonesBox, topFillColor1: zonesRgba, topFillColor2: zonesRgba, bottomLineColor: c.zonesBox, bottomFillColor1: zonesRgba, bottomFillColor2: zonesRgba });
						belowBoxSeries.applyOptions({ topLineColor: c.zonesBox, topFillColor1: zonesRgba, topFillColor2: zonesRgba, bottomLineColor: c.zonesBox, bottomFillColor1: zonesRgba, bottomFillColor2: zonesRgba });
						aboveBoxBottomLine.applyOptions({ color: c.zonesBox });
						belowBoxBottomLine.applyOptions({ color: c.zonesBox });

						const middleRgba = hexToRgba(c.middleZone, 0.25);
						smpBmlBoxSeries.applyOptions({ topLineColor: c.middleZone, topFillColor1: middleRgba, topFillColor2: middleRgba, bottomLineColor: c.middleZone, bottomFillColor1: middleRgba, bottomFillColor2: middleRgba });
						smpBmlBoxBottomLine.applyOptions({ color: c.middleZone });

						gammaBandSeries.applyOptions({ color: c.gammaBand });
						smartLiqUpperSeries.applyOptions({ color: c.highResistance });
						smartLiqLowerSeries.applyOptions({ color: c.lowSupport });

						// The dominance dots bake their color in at draw time (see
						// refreshLiveBandDots() above) rather than reading a
						// series-level option, so they need a redraw to pick up a
						// changed color immediately — harmless no-op if Bands is
						// currently off/not fetched yet. Sequenced, same reason as
						// onToggleBands() above.
						if (SHOW_BANDS) { refreshBands().then(refreshLiveBandDots); }

						// Max Pain also bakes its color in at draw time via
						// createPriceLine (see drawStrikeGammaLines), same
						// reasoning as the dominance dots above — harmless no-op
						// on /chart/<asset> and /oi/<asset>, where
						// SHOW_STRIKE_GAMMA is always false.
						if (SHOW_STRIKE_GAMMA) { refreshStrikeGamma(); }
					}

					function openSettingsModal() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						document.getElementById('settings-modal').style.display = 'flex';
					}

					function closeSettingsModal() {
						document.getElementById('settings-modal').style.display = 'none';
					}

					function saveChartColors() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) chartColors[key] = input.value;
						});
						localStorage.setItem(COLOR_STORAGE_KEY, JSON.stringify(chartColors));
						applyChartColors();
						closeSettingsModal();
					}

					function resetChartColors() {
						chartColors = Object.assign({}, DEFAULT_COLORS);
						localStorage.removeItem(COLOR_STORAGE_KEY);
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						applyChartColors();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: axisBlack(), title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: axisBlack(), title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					async function init() {
						try { await loadCandles(); await refreshDeltaZero(); await refreshMonthlyDeltaZero(); await refreshAllDeltaZero(); await refreshTomorrowDeltaZero(); await refreshDayAfterTomorrowDeltaZero(); await refreshBands(); await refreshLiveBandDots(); await refreshZonesBoxes(); await refreshNearestExpiry(); await refreshGammaTops(); await refreshStrikeGamma(); await updateForecastVisibility(); }
						catch (e) { setStatus('Error: ' + e.message); }
					}
					init();
					setInterval(updateLatestCandle, 5000);
					setInterval(refreshDeltaZero, REFRESH);
					setInterval(refreshMonthlyDeltaZero, REFRESH);
					setInterval(refreshNearestExpiry, REFRESH);
					setInterval(refreshAllDeltaZero, REFRESH);
					setInterval(refreshTomorrowDeltaZero, REFRESH);
					setInterval(refreshDayAfterTomorrowDeltaZero, REFRESH);
					// Bands polls on ZONES_BOX_REFRESH (not REFRESH) — its own
					// underlying dankbit.bands rows only ever change once per
					// hourly compute_snapshot() cron tick, so polling any faster
					// just re-fetches identical data; syncing it to the same
					// (slower) interval Zones already uses cuts wasted requests
					// with zero loss of real freshness, which matters more now
					// that this addon is heading toward more concurrent users.
					// refreshLiveBandDots() shares the same rationale — its own
					// dankbit.live.band rows are also hourly-cron-fed. Sequenced
					// into one interval (rather than two independent ones) since
					// refreshLiveBandDots() now reads smartLiqUpperPoints/
					// smartLiqLowerPoints, which only refreshBands() populates.
					setInterval(() => { refreshBands().then(refreshLiveBandDots); }, ZONES_BOX_REFRESH);
					setInterval(refreshZonesBoxes, ZONES_BOX_REFRESH);
					setInterval(refreshGammaTops, REFRESH);
					setInterval(refreshStrikeGamma, REFRESH);
					setInterval(refreshForecast, REFRESH);
				//
